"use strict";
import { useAccount, useReadContract, useWaitForTransactionReceipt, useWriteContract } from "wagmi";
import { useCallback, useMemo } from "react";
import { useEip5792Support } from "uniswap/src/features/transactions/swap/contexts/hooks/useEip5792Support";
import { useConnectorClient } from "wagmi";
import { encodeFunctionData, maxUint256 } from "viem";
const ERC20_ABI = [
  {
    inputs: [
      { internalType: "address", name: "spender", type: "address" },
      { internalType: "uint256", name: "amount", type: "uint256" }
    ],
    name: "approve",
    outputs: [{ internalType: "bool", name: "", type: "bool" }],
    stateMutability: "nonpayable",
    type: "function"
  },
  {
    inputs: [
      { internalType: "address", name: "owner", type: "address" },
      { internalType: "address", name: "spender", type: "address" }
    ],
    name: "allowance",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  }
];
const BRIBE_ABI = [
  {
    inputs: [
      { internalType: "address", name: "token", type: "address" },
      { internalType: "uint256", name: "amount", type: "uint256" }
    ],
    name: "notifyRewardAmount",
    outputs: [],
    stateMutability: "nonpayable",
    type: "function"
  }
];
export function useIncentiveContract({ selectedPool, incentiveToken, incentiveAmount }) {
  const { address: account, chainId } = useAccount();
  const { data: client } = useConnectorClient();
  const bribeAddress = selectedPool?.gauge?.bribeContract;
  const tokenAddress = incentiveToken?.address;
  const supportsEip5792 = useEip5792Support(chainId);
  const { writeContract, data: transactionHash, isPending: isWritePending, error: writeError } = useWriteContract();
  const {
    isLoading: isConfirming,
    isSuccess,
    error: receiptError
  } = useWaitForTransactionReceipt({
    hash: transactionHash
  });
  const { data: allowance, refetch: refetchAllowance } = useReadContract({
    address: tokenAddress,
    abi: ERC20_ABI,
    functionName: "allowance",
    args: account && bribeAddress ? [account, bribeAddress] : void 0,
    query: { enabled: !!tokenAddress && !!bribeAddress && !!account }
  });
  const needsApproval = useCallback((amount) => {
    if (!allowance || !amount) return true;
    const amountBigInt = BigInt(amount.quotient.toString());
    return allowance < amountBigInt;
  }, [allowance]);
  const approveToken = useCallback(async (_amount) => {
    if (!tokenAddress || !bribeAddress) {
      throw new Error("Missing contract addresses");
    }
    await writeContract({
      address: tokenAddress,
      abi: ERC20_ABI,
      functionName: "approve",
      args: [bribeAddress, maxUint256]
    });
  }, [writeContract, tokenAddress, bribeAddress]);
  const createIncentive = useCallback(async (params) => {
    if (!tokenAddress || !bribeAddress) {
      throw new Error("Missing contract addresses");
    }
    const amount = BigInt(params.amount.quotient.toString());
    await writeContract({
      address: bribeAddress,
      abi: BRIBE_ABI,
      functionName: "notifyRewardAmount",
      args: [tokenAddress, amount]
    });
  }, [writeContract, tokenAddress, bribeAddress]);
  const createIncentiveBatched = useCallback(async (params) => {
    if (!tokenAddress || !bribeAddress || !client || !account) {
      throw new Error("Missing parameters for batched transaction");
    }
    const amount = BigInt(params.amount.quotient.toString());
    const approveData = encodeFunctionData({
      abi: ERC20_ABI,
      functionName: "approve",
      args: [bribeAddress, maxUint256]
    });
    const incentiveData = encodeFunctionData({
      abi: BRIBE_ABI,
      functionName: "notifyRewardAmount",
      args: [tokenAddress, amount]
    });
    console.log("Batched incentive call data:", {
      approveData,
      incentiveData,
      tokenAddress,
      bribeAddress,
      amount: amount.toString(),
      approvalAmount: "max (unlimited)"
    });
    const result = await client.request({
      method: "wallet_sendCalls",
      params: [{
        version: "2.0.0",
        chainId: `0x${chainId?.toString(16)}`,
        from: account,
        calls: [
          {
            to: tokenAddress,
            data: approveData,
            value: "0x0"
          },
          {
            to: bribeAddress,
            data: incentiveData,
            value: "0x0"
          }
        ],
        atomicRequired: true
      }]
    });
    return result?.id;
  }, [client, account, chainId, tokenAddress, bribeAddress]);
  return useMemo(() => ({
    // Actions
    approveToken,
    createIncentive,
    createIncentiveBatched,
    // State checks
    needsApproval,
    // Transaction states
    isWritePending,
    isConfirming,
    isSuccess,
    writeError: writeError || receiptError,
    transactionHash,
    // Contract addresses
    bribeAddress,
    tokenAddress,
    // Allowance management
    allowance,
    refetchAllowance,
    // Batching support
    supportsEip5792
  }), [
    approveToken,
    createIncentive,
    createIncentiveBatched,
    needsApproval,
    isWritePending,
    isConfirming,
    isSuccess,
    writeError,
    receiptError,
    transactionHash,
    bribeAddress,
    tokenAddress,
    allowance,
    refetchAllowance,
    supportsEip5792
  ]);
}
